package com.ias.finance;
import org.junit.jupiter.api.*;
import org.h2.tools.RunScript;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.finance.JdbcMoneyLedger.*;
import static com.ias.finance.MoneyLedger.*;

/** Explicit component authority fixtures; real owner TLS remains an integration gate. */
class ManualMoneyFactsTest {
 JdbcFeeGroupsTest f;JdbcMoneyLedger ledger;UUID bill=UUID.randomUUID(),line=UUID.randomUUID();
 @BeforeEach void setup()throws Exception{f=new JdbcFeeGroupsTest();f.setup();try(var db=f.source.getConnection()){RunScript.execute(db,new InputStreamReader(getClass().getResourceAsStream("/db/migration/V6__manual_money_facts.sql"),StandardCharsets.UTF_8));}
  ledger=new JdbcMoneyLedger(f.source,new Authority(){public void current(JdbcFeeGroups.Actor a,FeeGroup.Identity o,String action){f.authority.current(a,o,action);}public void verify(JdbcFeeGroups.Actor a,FeeGroup.Identity o,UUID op,Command c){}public void recorded(Connection db,JdbcFeeGroups.Actor a,FeeGroup.Identity o,UUID op,Command c)throws SQLException{ManualMoneyFacts.append(db,a,o,op,c);}});
  ledger.apply(f.actor,f.owner,UUID.randomUUID(),new Assess(0,0,bill,new Approval(UUID.randomUUID(),"a".repeat(64),Map.of(line,100000L))));}
 Voucher voucher(String ref){return new Voucher(ref,LocalDate.of(2026,10,24),"OFFLINE_BANK",UUID.randomUUID(),"b".repeat(64));}
 @Test void manualAssertionAndReceiptCommitExactlyOnce()throws Exception{UUID op=UUID.randomUUID();var c=new Collect(1,0,bill,new Payment(UUID.randomUUID(),bill,80000,voucher("manual-original")));var result=ledger.apply(f.actor,f.owner,op,c);assertEquals(result,ledger.apply(f.actor,f.owner,op,c));assertEquals(1,f.count("finance_manual_money_fact"));assertEquals(1,f.count("finance_money_terminal_fact"));assertEquals(80000,ledger.read(f.actor,f.owner).collected());try(var db=f.source.getConnection();var q=db.prepareStatement("SELECT authority_digest,terminal_event_type,terminal_event_version FROM finance_money_terminal_fact WHERE operation_id=?")){q.setString(1,op.toString());try(var rows=q.executeQuery()){assertTrue(rows.next());assertEquals(MoneyAuthorityFacts.binding(f.actor,f.owner,op,c).authorityDigest(),rows.getString(1));assertEquals("FINANCE_COLLECTION_FINALIZED",rows.getString(2));assertEquals("1",rows.getString(3));}}}
 @Test void auditFailureRollsBackManualAssertionAndBalanceThenOriginalRecovers()throws Exception{UUID op=UUID.randomUUID();var c=new Collect(1,0,bill,new Payment(UUID.randomUUID(),bill,80000,voucher("audit-rollback")));try(var db=f.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit ADD CONSTRAINT manual_audit_fault CHECK(action_name<>'COLLECTION_RECORDED')");}assertThrows(SQLException.class,()->ledger.apply(f.actor,f.owner,op,c));assertEquals(0,f.count("finance_manual_money_fact"));assertEquals(0,f.count("finance_money_terminal_fact"));assertEquals(0,ledger.read(f.actor,f.owner).collected());try(var db=f.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit DROP CONSTRAINT manual_audit_fault");}ledger.apply(f.actor,f.owner,op,c);assertEquals(1,f.count("finance_manual_money_fact"));assertEquals(1,f.count("finance_money_terminal_fact"));}
 @Test void nonzeroCorrectionIsSingleVersionAtomicAndRetainsOriginalMoneyHistory()throws Exception{var original=new Payment(UUID.randomUUID(),bill,90000,voucher("same-bank-reference"));ledger.apply(f.actor,f.owner,UUID.randomUUID(),new Collect(1,0,bill,original));var corrected=new Payment(UUID.randomUUID(),bill,80000,voucher("same-bank-reference"),original.id());UUID op=UUID.randomUUID();var command=new Rebook(2,0,original.id(),UUID.randomUUID(),"人工核验原金额错录后同事务冲正重记",corrected);var receipt=ledger.apply(f.actor,f.owner,op,command);assertEquals(3,receipt.balance().version());assertEquals(80000,receipt.balance().collected());assertEquals(0,receipt.balance().refunded());assertEquals(2,receipt.balance().payments().size());assertTrue(receipt.balance().reversed().contains(original.id()));assertEquals(receipt,ledger.apply(f.actor,f.owner,op,command));assertEquals(2,f.count("finance_manual_money_fact"));assertEquals(3,f.count("finance_money_entry"));}
 @Test void failedRebookingNeverPersistsZeroBalanceOrLosesOriginal()throws Exception{var original=new Payment(UUID.randomUUID(),bill,90000,voucher("rebook-fault-reference"));ledger.apply(f.actor,f.owner,UUID.randomUUID(),new Collect(1,0,bill,original));var corrected=new Payment(UUID.randomUUID(),bill,80000,voucher("rebook-fault-reference"),original.id());var command=new Rebook(2,0,original.id(),UUID.randomUUID(),"人工核验非零实际到账保留",corrected);try(var db=f.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit ADD CONSTRAINT rebook_audit_fault CHECK(action_name<>'COLLECTION_REBOOKED')");}assertThrows(SQLException.class,()->ledger.apply(f.actor,f.owner,UUID.randomUUID(),command));var state=ledger.read(f.actor,f.owner);assertEquals(90000,state.collected());assertEquals(2,state.version());assertFalse(state.reversed().contains(original.id()));assertEquals(1,f.count("finance_manual_money_fact"));}
}
